<?php $page_title='Medical Records';require_once __DIR__.'/../includes/header.php';$rows=$pdo->query("SELECT r.*,p.name patient,d.name doctor FROM medical_records r JOIN patients p ON p.id=r.patient_id JOIN doctors d ON d.id=r.doctor_id ORDER BY r.id DESC")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Medical Records</h2><a href="add.php" class="btn btn-primary">+ Add Record</a></div><div class="card p-3"><table class="table"><thead><tr><th>Date</th><th>Patient</th><th>Doctor</th><th>Diagnosis</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['visit_date']?></td><td><?=e($r['patient'])?></td><td><?=e($r['doctor'])?></td><td><?=e($r['diagnosis'])?></td><td><?=e($r['notes'])?></td></tr><?php endforeach;?></tbody></table></div><?php require_once __DIR__.'/../includes/footer.php';?>